#define _GNU_SOURCE
#include <sys/mman.h>
#include <sys/resource.h>
#include <unistd.h>
#include <fcntl.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>

int main(void) {
    long page=sysconf(_SC_PAGESIZE);
    const size_t pages=4;
    int fd=-1, status=2;
    char name[]="opsf-file-fault-XXXXXX";
    unsigned char *source=NULL,*mapping=MAP_FAILED, resident[4]={0};
    struct rusage before={0},read_done={0},write_done={0};
    if(page<=0 || page>65536) goto cleanup;
    size_t bytes=(size_t)page*pages;
    source=malloc(bytes);if(!source) goto cleanup;
    memset(source,0x31,bytes);
    fd=mkstemp(name);if(fd<0) goto cleanup;
    if(write(fd,source,bytes)!=(ssize_t)bytes || fsync(fd)) goto cleanup;
    int advised=posix_fadvise(fd,0,(off_t)bytes,POSIX_FADV_DONTNEED);
    if(advised){errno=advised;goto cleanup;}
    mapping=mmap(NULL,bytes,PROT_READ|PROT_WRITE,MAP_PRIVATE,fd,0);
    if(mapping==MAP_FAILED || madvise(mapping,bytes,MADV_NOHUGEPAGE)) goto cleanup;
    if(mincore(mapping,bytes,resident)) goto cleanup;
    for(size_t i=0;i<pages;i++) if(resident[i]&1){errno=EBUSY;goto cleanup;}
    /* Warm the counter structures; process-wide counts are not an exact per-page I/O trace. */
    getrusage(RUSAGE_SELF,&before);getrusage(RUSAGE_SELF,&read_done);getrusage(RUSAGE_SELF,&write_done);
    volatile unsigned char *view=mapping;
    volatile unsigned long sum=0;
    if(getrusage(RUSAGE_SELF,&before)) goto cleanup;
    for(size_t i=0;i<pages;i++) sum+=view[i*(size_t)page];
    if(getrusage(RUSAGE_SELF,&read_done)) goto cleanup;
    for(size_t i=0;i<pages;i++) view[i*(size_t)page]=0x52;
    if(getrusage(RUSAGE_SELF,&write_done)) goto cleanup;
    unsigned char check;
    for(size_t i=0;i<pages;i++) {
        if(pread(fd,&check,1,(off_t)(i*(size_t)page))!=1 || check!=0x31 || view[i*(size_t)page]!=0x52) goto cleanup;
    }
    printf("{\"page_size\":%ld,\"pages\":%zu,\"cold_file_major\":%ld,\"cold_file_minor\":%ld,\"cow_minor\":%ld,\"cow_major\":%ld,\"sum\":%lu,\"uid\":%lu}\n",page,pages,read_done.ru_majflt-before.ru_majflt,read_done.ru_minflt-before.ru_minflt,write_done.ru_minflt-read_done.ru_minflt,write_done.ru_majflt-read_done.ru_majflt,sum,(unsigned long)getuid());
    status=(read_done.ru_majflt>before.ru_majflt && write_done.ru_minflt-read_done.ru_minflt>=(long)pages && write_done.ru_majflt==read_done.ru_majflt)?0:3;
cleanup:
    if(status==2) fprintf(stderr,"file-fault capability unavailable: errno=%d (%s)\n",errno,strerror(errno));
    if(mapping!=MAP_FAILED) munmap(mapping,(size_t)page*pages);
    if(fd>=0){close(fd);unlink(name);}
    free(source);
    return status;
}
